"""Derived local viewer for v2 evidence and separately signed review state."""
import html
import json
from pathlib import Path


def render(directory,bundle,review=None):
    directory=Path(directory);bundle=Path(bundle)
    import os
    relative=os.path.relpath(bundle,directory)
    manifest=json.loads((bundle/'merkle/merkle_manifest.json').read_text())
    cross=json.loads((bundle/'market_data/cross_reference.json').read_text())
    faults=json.loads((bundle/'fault_campaign.json').read_text()) if (bundle/'fault_campaign.json').exists() else {'detected':0,'total':0}
    state=review or {'state':'awaiting_review','identity_scope':'No independent approval signatures supplied'}
    leaf=next(item for item in manifest['leaves'] if item['path']=='ensemble_trades.csv')
    def link(name):return html.escape(relative+'/'+name,quote=True)
    run=directory.name if directory.name.startswith('langgraph_') else 'v2' if directory.name=='v2_demo' else 'demo'
    page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Portfolio Proof v2</title><style>body{{margin:0;background:#07131f;color:#e8f0f8;font:16px/1.6 system-ui}}main{{max-width:1100px;margin:auto;padding:40px 24px}}h1{{font-size:48px;line-height:1.1}}.tag,a{{color:#58dfc3}}.cards{{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}}.card,details{{background:#12273a;border:1px solid #29485e;border-radius:14px;padding:20px;margin:16px 0}}strong{{display:block;font-size:26px}}code{{overflow-wrap:anywhere}}.flow{{font-size:20px;padding:24px;border-left:4px solid #58dfc3;background:#102133}}small{{color:#b1c6d6}}summary{{cursor:pointer}}a{{margin-right:14px}}</style></head><body><main><p><a href="http://127.0.0.1:8765/?view=overview&amp;run={run}">打开完整交互工作台 →</a> <small>先在仓库运行 make serve；本页保留证据的静态副本。</small></p><div class="tag">LANGGRAPH · EXECUTION TRACES · MULTIPARTY REVIEW</div><h1>Evidence you can inspect.<br>Reviews you can attribute.</h1><div class="flow">Goal → Agent ⇄ Tools → Replay → Merkle bundle → Publisher + Reviewer</div><div class="cards"><div class="card"><small>Merkle evidence</small><strong>{manifest['leaf_count']} files</strong>Exact-byte, path-bound proofs</div><div class="card"><small>Cross-source checks</small><strong>{cross['compared_rows']} closes</strong>Binance USDT / Coinbase USD</div><div class="card"><small>Fault campaign</small><strong>{faults['detected']} / {faults['total']}</strong>Injected defects detected</div><div class="card"><small>Review protocol state</small><strong>{html.escape(state['state'])}</strong>Distinct publisher and reviewer keys</div></div><p>Committed root<br><code>{manifest['root']}</code></p><p>{html.escape(state.get('identity_scope',''))}</p><details open><summary>Inspect research and execution</summary><p><a href="{link('index.html')}">Research result</a><a href="{link('agent_events.jsonl')}">Agent tool trace</a><a href="{link('ensemble_ledger.csv')}">Execution ledger</a><a href="{link('fault_campaign.json')}">Fault campaign</a></p></details><details><summary>Verify one selected file</summary><p><a href="{link('ensemble_trades.csv')}">Trade file</a><a href="{link(leaf['proof_path'])}">Its Merkle proof</a><a href="{link('merkle/merkle_manifest.json')}">Manifest</a></p><p>Use the signed root as the trust anchor. A reviewer needs only this file, its path and proof to check inclusion; other committed files can remain unavailable.</p></details><details><summary>Understand the market-data boundary</summary><p><a href="{link('market_data/quality.json')}">Quality checks</a><a href="{link('market_data/cross_reference.json')}">Cross-source report</a></p><p>{html.escape(cross['truth_claim'])} Different exchange prices and USD/USDT quotes are compared with an explicit {cross['tolerance_bps']} bps tolerance. Hash agreement alone does not prove truth. Source downtime or disputed values block the research tool.</p></details><details><summary>Understand the review boundary</summary><p>Signatures bind the root, role, decision and trusted policy hash. Signatures do not establish the human owner of a key. Demo keys represent a local protocol simulation; genuine independent review requires separately held keys. The v2 bundle is not automatically anchored on a public blockchain.</p></details></main></body></html>'''
    (directory/'index.html').write_text(page)
